package pythonarraytest

import (
	"github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

// Bitmask indicating which fields contain valid data in a FOLLOW_TARGET message (lat/lon/alt, vel, acc, attitude_q, rates). If a bit is unset, the corresponding field(s) are zero-filled and should be ignored.
type FOLLOW_TARGET_CAP_FLAGS = common.FOLLOW_TARGET_CAP_FLAGS

const (
	// Position estimate is valid (lat/lon/alt).
	FOLLOW_TARGET_CAP_FLAGS_POS FOLLOW_TARGET_CAP_FLAGS = common.FOLLOW_TARGET_CAP_FLAGS_POS
	// Velocity estimate is valid (vel field).
	FOLLOW_TARGET_CAP_FLAGS_VEL FOLLOW_TARGET_CAP_FLAGS = common.FOLLOW_TARGET_CAP_FLAGS_VEL
	// Acceleration estimate is valid (acc field).
	FOLLOW_TARGET_CAP_FLAGS_ACCEL FOLLOW_TARGET_CAP_FLAGS = common.FOLLOW_TARGET_CAP_FLAGS_ACCEL
	// Attitude and angular rate estimates are valid (attitude_q and rates fields).
	FOLLOW_TARGET_CAP_FLAGS_ATT_RATES FOLLOW_TARGET_CAP_FLAGS = common.FOLLOW_TARGET_CAP_FLAGS_ATT_RATES
)
